/* DFSWM Compliance Plugin - browser bundle (generated by scripts/build-browser.js) */
(function () {
  "use strict";
  var modules = {};

  function def(id, fn) { modules[id] = { fn: fn, exports: {}, loaded: false }; }

  // Resolve a require specifier (e.g. "./model.js", "../engine/model.js")
  // against the caller's module key (e.g. "word/extractor.js").
  function resolve(caller, spec) {
    var id = String(spec);
    if (id.charAt(0) !== ".") return id; // bare identifier
    var dir = caller.indexOf("/") === -1 ? "" : caller.slice(0, caller.lastIndexOf("/"));
    var parts = dir ? dir.split("/") : [];
    id.split("/").forEach(function (seg) {
      if (seg === "." || seg === "") return;
      if (seg === "..") parts.pop();
      else parts.push(seg);
    });
    return parts.join("/");
  }

  function makeRequire(caller) {
    return function (id) {
      var key = resolve(caller, id);
      var m = modules[key];
      if (!m) throw new Error("Module not found: " + id + " (key: " + key + ")");
      if (!m.loaded) {
        m.loaded = true;
        m.fn(m, m.exports, makeRequire(key));
      }
      return m.exports;
    };
  }

def("engine/model.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — document model.
 *
 * The Word task pane extracts the open document into this plain, serialisable
 * model via the Word JavaScript API (see ../word/extractor.js). The engine
 * (evaluators.js / engine.js) only ever sees this model, so the same code runs
 * in Node for tests and in the browser for live checking.
 *
 * Paragraph fields:
 *   text            plain text of the paragraph
 *   style           Word style name, if any ("Normal", "Heading 1", ...)
 *   fontName        e.g. "Times New Roman"
 *   fontSize        in points
 *   bold / italic / underline   booleans (underline: any underline)
 *   allCaps         whether the run is formatted ALL CAPS (Word property)
 *   alignment       "left" | "center" | "right" | "justified"
 *   firstLineIndentCm / blockIndentCm
 *   lineSpacing     "single" | "double" | "oneAndHalf" | numeric multiplier
 *   keepWithNext    paragraph.keepWithNext
 *   keepPrevious    paragraph.keepPrevious
 *   headingLevel    null | "subject" | "main" | "group" | "paragraph"
 *   pageBreakBefore true when the paragraph starts a new page
 *   slideIndex      slide number (0-based) when the paragraph came from a
 *                   PowerPoint slide; null for Word documents
 *
 * Section fields:
 *   margins   { left, right, top, bottom } in cm
 *   headerDistanceCm / footerDistanceCm
 *   headers / footers — { primary, firstPage, evenPages } text arrays
 *
 * Top-level:
 *   docType   selected document type (see dfswm-rulesets/index.json)
 *   bodyText  convenience concatenation of all paragraph text
 */
"use strict";

const CM_PER_POINT = 2.54 / 72; // 1 pt = 1/72 in = 2.54/72 cm

function pointsToCm(pt) {
  return typeof pt === "number" ? pt * CM_PER_POINT : null;
}

/**
 * Convert raw extracted data into a validated, normalised model.
 * `raw` may already be a model (idempotent).
 */
function normalizeModel(raw) {
  if (!raw || typeof raw !== "object") {
    throw new Error("model must be an object");
  }
  const paragraphs = (raw.paragraphs || []).map((p, i) => ({
    index: i,
    text: String(p.text ?? ""),
    style: p.style || null,
    fontName: p.fontName || null,
    fontSize: p.fontSize ?? null,
    bold: !!p.bold,
    italic: !!p.italic,
    underline: !!p.underline,
    allCaps: !!p.allCaps,
    alignment: p.alignment || "left",
    firstLineIndentCm: p.firstLineIndentCm ?? null,
    blockIndentCm: p.blockIndentCm ?? null,
    lineSpacing: p.lineSpacing ?? null,
    keepWithNext: !!p.keepWithNext,
    keepPrevious: !!p.keepPrevious,
    headingLevel: p.headingLevel || null,
    pageBreakBefore: !!p.pageBreakBefore,
    slideIndex: p.slideIndex != null ? p.slideIndex : null,
  }));
  const sections = (raw.sections || []).map((s) => ({
    margins: s.margins || { left: null, right: null, top: null, bottom: null },
    headerDistanceCm: s.headerDistanceCm ?? null,
    footerDistanceCm: s.footerDistanceCm ?? null,
    headers: s.headers || { primary: [], firstPage: [], evenPages: [] },
    footers: s.footers || { primary: [], firstPage: [], evenPages: [] },
  }));
  const tables = (raw.tables || []).map((t) => ({
    headerRow: (t.headerRow || []).map((c) => String(c.text ?? c ?? "")),
    rows: (t.rows || []).map((r) => r.map((c) => ({
      text: String(c.text ?? ""),
      fontSize: c.fontSize ?? null,
    }))),
  }));
  const footnotes = (raw.footnotes || []).map((f) => ({
    text: String(f.text ?? ""),
    fontSize: f.fontSize ?? null,
  }));

  const model = {
    docType: raw.docType || "general",
    paragraphs,
    sections,
    tables,
    footnotes,
    title: raw.title || null,
  };
  model.bodyText = paragraphs.map((p) => p.text).join("\n");
  return model;
}

/** True when the paragraph text is blank/whitespace only. */
function isBlankParagraph(p) {
  return !p.text || p.text.trim().length === 0;
}

/**
 * Resolve which paragraphs a check scope covers. Falls back to all
 * paragraphs for scopes that cannot be resolved precisely.
 */
function paragraphsForScope(model, scope) {
  const all = model.paragraphs;
  switch (scope) {
    case "body":
    case "all":
      return all;
    case "subject-heading":
      return all.filter((p) => p.headingLevel === "subject");
    case "main-heading":
      return all.filter((p) => p.headingLevel === "main");
    case "group-heading":
      return all.filter((p) => p.headingLevel === "group");
    case "paragraph-heading":
      return all.filter((p) => p.headingLevel === "paragraph");
    case "heading":
      return all.filter((p) => p.headingLevel != null);
    case "signature-block": {
      const nonBlank = all.filter((p) => !isBlankParagraph(p));
      return nonBlank.slice(-3);
    }
    case "first-page": {
      // Presentations: "first page" is slide 1.
      if (all.some((p) => p.slideIndex != null)) {
        return all.filter((p) => p.slideIndex === 0);
      }
      const cut = all.findIndex((p) => p.pageBreakBefore && p.index > 0);
      const end = cut === -1 ? Math.min(10, all.length) : cut;
      return all.slice(0, end);
    }
    default:
      return all;
  }
}

/** Plain text of a scope (for regex/element checks). */
function textForScope(model, scope) {
  const parts = paragraphsForScope(model, scope).map((p) => p.text);
  if (scope === "header" || scope === "footer") {
    const secText = [];
    for (const s of model.sections) {
      const bag = scope === "header" ? s.headers : s.footers;
      for (const kind of ["primary", "firstPage", "evenPages"]) {
        secText.push(...(bag[kind] || []));
      }
    }
    return secText.join("\n");
  }
  if (scope === "table") {
    return model.tables
      .map((t) => t.rows.map((r) => r.map((c) => c.text).join(" | ")).join("\n"))
      .join("\n");
  }
  if (scope === "table-column-head") {
    return model.tables.map((t) => t.headerRow.join(" | ")).join("\n");
  }
  if (scope === "footnote") {
    return model.footnotes.map((f) => f.text).join("\n");
  }
  return parts.join("\n");
}

/** All document text including headers, footers, tables and footnotes. */
function fullText(model) {
  const bits = [model.bodyText];
  for (const s of model.sections) {
    for (const bag of [s.headers, s.footers]) {
      for (const kind of ["primary", "firstPage", "evenPages"]) {
        bits.push((bag[kind] || []).join("\n"));
      }
    }
  }
  bits.push(
    model.tables.map((t) => t.rows.map((r) => r.map((c) => c.text).join(" ")).join("\n")).join("\n"),
  );
  bits.push(model.footnotes.map((f) => f.text).join("\n"));
  return bits.join("\n");
}

module.exports = {
  CM_PER_POINT,
  pointsToCm,
  normalizeModel,
  isBlankParagraph,
  paragraphsForScope,
  textForScope,
  fullText,
};

});

def("engine/evaluators.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — evaluators.
 *
 * Each evaluator has the signature:
 *   (model, rule, ctx) => Finding[]
 *
 * model  — normalised document model (see model.js)
 * rule   — the ruleset rule object (id, severity, check, autofix, ...)
 * ctx    — { references } optional reference data (e.g. Ch 16 abbreviations)
 *
 * A Finding is:
 *   { ruleId, severity, title, description, chapter, paragraphs,
 *     message, locations: [{ paragraphIndex?, snippet? }],
 *     fix: { action, params } | null, checkable: bool, manual?: bool }
 *
 * An evaluator that cannot be reliably automated returns a single
 * finding with checkable:false (rendered as a checklist item).
 */
"use strict";

const {
  pointsToCm,
  isBlankParagraph,
  paragraphsForScope,
  textForScope,
  fullText,
} = require("./model.js");

const RANKS = /\b(Lt Col|Lieutenant Colonel|Maj|Major|Capt|Captain|Lt|Lieutenant|WO|Warrant Officer|Sgt|Sergeant|Cpl|Corporal|Brig|Brigadier|Col|Colonel|Gen|General|SO1|SO2|SO3)\b/;

function finding(rule, message, opts = {}) {
  return {
    ruleId: rule.id,
    severity: rule.severity || "warning",
    title: rule.title || rule.id,
    description: rule.description || "",
    chapter: rule.chapter || "",
    paragraphs: rule.paragraphs || "",
    message,
    locations: opts.locations || [],
    fix: opts.fix !== undefined ? opts.fix : null,
    checkable: opts.checkable !== false,
  };
}

function uncheckable(rule, message) {
  return { ...finding(rule, message), checkable: false };
}

function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const EVALUATORS = {};

/* ------------------------------------------------------------------ */
/* Core formatting                                                     */
/* ------------------------------------------------------------------ */

EVALUATORS["font-name"] = (model, rule) => {
  const allowed = (rule.check.params.allowed || []).map((f) => f.toLowerCase());
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && p.fontName && !allowed.includes(p.fontName.toLowerCase()));
  if (!bad.length) return [];
  return [finding(rule, `Font '${bad[0].fontName}' is not one of the allowed fonts (${rule.check.params.allowed.join(", ")}).`, {
    locations: bad.map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "setFont", params: { fontName: rule.check.params.allowed[0] } },
  })];
};

EVALUATORS["font-size"] = (model, rule) => {
  const { size, comparison = "eq" } = rule.check.params;
  const scope = rule.check.scope;

  if (scope === "table") {
    if (!model.tables.length) return [uncheckable(rule, "No tables in the document.")];
    const bad = [];
    for (const t of model.tables) {
      for (const row of t.rows) {
        for (const cell of row) {
          if (cell.fontSize != null && cell.fontSize !== size) bad.push(cell);
        }
      }
    }
    if (!bad.length) return [];
    return [finding(rule, `${bad.length} table cell(s) are not ${size} pt (e.g. ${bad[0].fontSize} pt).`)];
  }

  if (scope === "footnote") {
    if (!model.footnotes.length) return [uncheckable(rule, "No footnote data extracted from the document.")];
    const bad = model.footnotes.filter((f) => f.fontSize != null && f.fontSize !== size);
    if (!bad.length) return [];
    return [finding(rule, `${bad.length} footnote(s) are not ${size} pt.`)];
  }

  const paragraphs = paragraphsForScope(model, scope);
  const bad = paragraphs.filter((p) => p.text.trim() && p.fontSize != null && p.fontSize !== size);
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} item(s) in scope '${scope}' are not ${size} pt (e.g. ${bad[0].fontSize} pt).`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "setFontSize", params: { size } },
  })];
};

EVALUATORS["justification"] = (model, rule) => {
  const want = rule.check.params.alignment || "justified";
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && p.alignment && p.alignment !== want);
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} paragraph(s) are not ${want} (e.g. '${bad[0].alignment}').`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "setAlignment", params: { alignment: want } },
  })];
};

EVALUATORS["bold"] = (model, rule) => {
  const expected = !!rule.check.params.expected;
  const scope = rule.check.scope;
  if (scope === "table-column-head") {
    return [uncheckable(rule, "Table header-row detection is not implemented; verify column headings are bold manually.")];
  }
  const paragraphs = paragraphsForScope(model, scope);
  const bad = paragraphs.filter((p) => p.text.trim() && p.bold !== expected);
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} item(s) in scope '${scope}' should be ${expected ? "bold" : "not bold"}.`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "setBold", params: { bold: expected } },
  })];
};

EVALUATORS["italic"] = (model, rule) => {
  const expected = !!rule.check.params.expected;
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && /[“"']/.test(p.text) && p.italic !== expected);
  if (!bad.length) return [];
  return [finding(rule, "Quoted text or publication titles should be italicised.", {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
  })];
};

EVALUATORS["underline"] = (model, rule) => {
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.underline);
  if (!bad.length) return [];
  return [finding(rule, `Underlining must not be used for emphasis in typed text (${bad.length} paragraph(s)).`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "removeUnderline", params: {} },
  })];
};

EVALUATORS["margin"] = (model, rule) => {
  const params = rule.check.params;
  const section = model.sections[0];
  if (!section) return [uncheckable(rule, "No section layout data available; check page margins manually.")];

  // Header/footer distance variant
  if (params.target === "header-footer") {
    const issues = [];
    if (section.headerDistanceCm != null && Math.abs(section.headerDistanceCm - params.valueCm) > 0.05) {
      issues.push(`header distance is ${section.headerDistanceCm.toFixed(2)} cm (should be ${params.valueCm} cm)`);
    }
    if (section.footerDistanceCm != null && Math.abs(section.footerDistanceCm - params.valueCm) > 0.05) {
      issues.push(`footer distance is ${section.footerDistanceCm.toFixed(2)} cm (should be ${params.valueCm} cm)`);
    }
    if (!issues.length) return [];
    return [finding(rule, issues.join("; ") + ".", {
      fix: { action: "setMargins", params: { sides: [], target: "header-footer", valueCm: params.valueCm } },
    })];
  }

  const m = section.margins || {};
  const issues = [];
  for (const side of params.sides || ["left", "right", "top", "bottom"]) {
    const v = m[side];
    if (v == null) continue;
    if (Math.abs(v - params.valueCm) > 0.05) {
      issues.push(`${side} margin is ${v.toFixed(2)} cm (should be ${params.valueCm} cm)`);
    }
  }
  if (!issues.length) return [];
  return [finding(rule, issues.join("; ") + ".", {
    fix: { action: "setMargins", params: { sides: params.sides || ["left", "right", "top", "bottom"], valueCm: params.valueCm } },
  })];
};

EVALUATORS["indent"] = (model, rule) => {
  const { firstLineCm, blockIndentCm } = rule.check.params;
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => {
    if (!p.text.trim()) return false;
    if (firstLineCm != null && p.firstLineIndentCm != null && Math.abs(p.firstLineIndentCm - firstLineCm) > 0.05) return true;
    if (blockIndentCm != null && p.blockIndentCm != null && Math.abs(p.blockIndentCm - blockIndentCm) > 0.05) return true;
    return false;
  });
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} paragraph(s) have incorrect indentation.`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
  })];
};

EVALUATORS["line-spacing"] = (model, rule) => {
  const allowed = Array.isArray(rule.check.params.spacing) ? rule.check.params.spacing : [rule.check.params.spacing];
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && p.lineSpacing && !allowed.includes(p.lineSpacing));
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} paragraph(s) use line spacing '${bad[0].lineSpacing}' (expected ${allowed.join(" or ")}).`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "setLineSpacing", params: { spacing: allowed[0] } },
  })];
};

EVALUATORS["blank-line"] = (model, rule) => {
  const scope = paragraphsForScope(model, rule.check.scope);
  if (!scope.length) return [];
  const lastNonBlank = [...scope].reverse().find((p) => !isBlankParagraph(p));
  if (!lastNonBlank) return [];
  const after = scope.slice(lastNonBlank.index + 1);
  const hasBlank = after.some((p) => isBlankParagraph(p));
  if (hasBlank) return [];
  return [uncheckable(rule, "No blank line detected between the last line of text and the page number; verify in Print Layout.")];
};

EVALUATORS["tab-stop"] = (model, rule) => {
  return [uncheckable(rule, "Tab stop intervals cannot be read from the document model; verify default tabs are 1.0 cm in Page Setup.")];
};

EVALUATORS["keep-with-next"] = (model, rule) => {
  const { keepWithNext = false, keepWithPrevious = false } = rule.check.params;
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && (keepWithNext ? !p.keepWithNext : !p.keepPrevious));
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} item(s) are at risk of being stranded at a page boundary (hanging heading / orphaned signature).`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "keepWithNext", params: { keepWithNext } },
  })];
};

EVALUATORS["page-number-position"] = (model, rule) => {
  const footerText = model.sections.map((s) => (s.footers.primary || []).join(" ")).join(" ").trim();
  if (footerText) return [];
  return [finding(rule, "No page number found in the footer (page numbers go at bottom centre, above the classification).", {
    fix: { action: "insertPageNumber", params: { position: rule.check.params.position || "center" } },
  })];
};

EVALUATORS["page-number-format"] = (model, rule) => {
  const fmt = rule.check.params.format;
  const footerText = model.sections.map((s) => (s.footers.primary || []).join(" ")).join(" ").trim();
  if (fmt === "X of Y") {
    if (/\d+\s*of\s*\d+/.test(footerText)) return [];
    return [finding(rule, "Footer page number must use the 'X of Y' total-pages format for this classification.")];
  }
  if (fmt === "annex-letter-page") {
    if (/^[A-Z]-\d+/.test(footerText)) return [];
    return [finding(rule, "Annex pages must be numbered with the annex letter (e.g. A-1, A-2).")];
  }
  return [uncheckable(rule, `Page numbering format '${fmt}' needs manual verification.`)];
};

EVALUATORS["heading-style"] = (model, rule) => {
  const params = rule.check.params;
  const scope = paragraphsForScope(model, rule.check.scope);
  if (!scope.length) return [];

  // Reference body size for the "+2pt" main-heading rule.
  let bodySize = null;
  if (params.sizeOffsetPoints) {
    const counts = {};
    for (const p of model.paragraphs) {
      if (p.headingLevel) continue;
      if (p.fontSize == null) continue;
      counts[p.fontSize] = (counts[p.fontSize] || 0) + 1;
    }
    const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
    bodySize = sorted.length ? Number(sorted[0][0]) : null;
  }

  const issues = [];
  for (const p of scope) {
    const list = [];
    if (params.alignment && p.alignment !== params.alignment) list.push(`alignment '${p.alignment}' (expected ${params.alignment})`);
    if (params.bold && !p.bold) list.push("not bold");
    if (params.caps && !p.allCaps && p.text !== p.text.toUpperCase()) list.push("not all capitals");
    if (params.titleCase && !/^([A-Z][a-z]+[\s,&\-–—]*)+/.test(p.text.trim())) list.push("not title case");
    if (params.noTrailingFullStop && /\.\s*$/.test(p.text.trim())) list.push("has trailing full stop");
    if (params.trailingFullStop && !/\.\s*$/.test(p.text.trim())) list.push("missing trailing full stop");
    if (params.sizeOffsetPoints && bodySize != null && p.fontSize != null && p.fontSize !== bodySize + params.sizeOffsetPoints) {
      list.push(`size ${p.fontSize} pt (expected ${bodySize + params.sizeOffsetPoints} pt)`);
    }
    if (list.length) issues.push({ p, list });
  }
  if (!issues.length) return [];
  return [finding(rule, `${issues.length} heading(s) do not conform: ${issues[0].list.join("; ")}.`, {
    locations: issues.map(({ p }) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    fix: { action: "fixHeading", params },
  })];
};

/* ------------------------------------------------------------------ */
/* Structure                                                           */
/* ------------------------------------------------------------------ */

EVALUATORS["required-element"] = (model, rule) => {
  const params = rule.check.params;
  const text = textForScope(model, rule.check.scope);

  // Keyword list: [{ id, pattern }] — each is a searchable regex.
  if (params.keywords) {
    const missing = params.keywords.filter((k) => !new RegExp(k.pattern || escapeRegExp(k.id), "i").test(text));
    if (!missing.length) return [];
    return [finding(rule, `Missing required element(s): ${missing.map((k) => k.id).join(", ")}.`)];
  }

  if (params.elements) {
    // Abstract concept ids (e.g. "file-reference") cannot be matched as
    // literal text; only verify element ids that are literal phrases
    // (contain a space), and mark abstract structural elements for review.
    const literalPhrases = params.elements.filter((el) => /\s/.test(el));
    if (literalPhrases.length) {
      const missing = literalPhrases.filter((el) => !text.toLowerCase().includes(el.toLowerCase()));
      if (missing.length) return [finding(rule, `Missing required element(s): ${missing.join(", ")}.`)];
      return [];
    }
    return [uncheckable(rule, `Verify ${params.elements.join(", ")} manually (structural elements cannot be auto-detected).`)];
  }

  if (params.keyword) {
    const found = new RegExp(params.keyword, "i").test(text);
    if (found) return [];
    return [finding(rule, `Required element '${params.keyword}' not found in scope '${rule.check.scope}'.`)];
  }

  if (params.rule) {
    return [uncheckable(rule, `Structural requirement '${params.rule}' needs manual verification.`)];
  }
  return [uncheckable(rule, "Required-element check needs a keyword, keywords, elements list, or rule.")];
};

EVALUATORS["element-order"] = (model, rule) => {
  const params = rule.check.params;
  const text = textForScope(model, rule.check.scope);

  if (params.mandatory) {
    const lines = text.split("\n").map((l) => l.trim().replace(/^\d+[.)]\s*/, "").toLowerCase());
    const wanted = params.mandatory.map((m) => m.toLowerCase());
    const positions = wanted.map((w) => lines.findIndex((l) => l === w));
    const missing = wanted.filter((w, i) => positions[i] === -1);
    if (missing.length) {
      return [finding(rule, `Mandatory heading(s) missing: ${missing.join(", ").toUpperCase()}.`)];
    }
    if (params.order !== false) {
      for (let i = 1; i < positions.length; i++) {
        if (positions[i] < positions[i - 1]) {
          return [finding(rule, `Headings out of order: '${params.mandatory[i].toUpperCase()}' appears before '${params.mandatory[i - 1].toUpperCase()}'.`)];
        }
      }
    }
    return [];
  }

  if (params.rule === "intro-body-conclusion") {
    return [uncheckable(rule, "Verify the letter text moves through introduction, body and conclusion.")];
  }
  if (params.rule === "conops-elements" || params.rule === "series-items" || params.rule === "aim-after-introduction") {
    return [uncheckable(rule, `Sequence rule '${params.rule}' needs manual verification.`)];
  }
  return [uncheckable(rule, "Order check needs mandatory headings or a rule.")];
};

// Numbering markers per level (1..5) of the DFSWM scheme.
const NUMBER_MARKERS = [
  { re: /^\d+\.\t/, label: "Arabic numeral + full stop + tab" }, // 1.
  { re: /^[a-z]\.\t/, label: "lower-case letter + full stop + tab" }, // a.
  { re: /^\(\d+\)\t/, label: "Arabic numeral in brackets + tab" }, // (1)
  { re: /^\([ivx]+\)\t/, label: "lower-case Roman in brackets + tab" }, // (a)
  { re: /^[ivx]+\.\t/, label: "lower-case Roman + full stop + tab" }, // i.
];

function levelFromIndent(p) {
  if (p.blockIndentCm == null) return 1;
  return Math.min(5, Math.max(1, Math.round(p.blockIndentCm / 1.0) + 1));
}

EVALUATORS["paragraph-numbering"] = (model, rule) => {
  const params = rule.check.params;
  const scope = paragraphsForScope(model, rule.check.scope);

  if (params.rule === "single-paragraph-not-numbered") {
    const numbered = scope.filter((p) => /^\d+\.\t|^\d+\.\s/.test(p.text.trim()));
    if (scope.length === 1 && numbered.length === 1) {
      return [finding(rule, "A single-paragraph document must not number its paragraph.")];
    }
    return [];
  }
  if (params.rule === "never-numbered" || params.rule === "prefer-un-numbered") {
    const numbered = scope.filter((p) => /^\d+\.\t|^\d+\.\s/.test(p.text.trim()));
    if (numbered.length) {
      return [finding(rule, `${numbered.length} paragraph(s) are numbered; paragraphs in this letter type should not be numbered.`, {
        locations: numbered.map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 60) })),
      })];
    }
    return [];
  }
  if (params.rule === "optional-numbering") return [];
  if (params.rule === "numbered-items-with-headings") {
    const items = scope.filter((p) => /^\d+\./.test(p.text.trim()));
    if (!items.length) return [finding(rule, "Agenda items should be numbered, each with a heading.")];
    return [];
  }

  // Hierarchy check: every numbered paragraph's marker must match its
  // indent level in the 1. a. (1) (a) i. scheme.
  const bad = [];
  for (const p of scope) {
    const t = p.text.trim();
    if (!/^(\d+\.|[a-z]\.|\(\d+\)|\([ivx]+\)|[ivx]+\.)\t/.test(t)) continue;
    const level = levelFromIndent(p);
    const marker = NUMBER_MARKERS[level - 1];
    if (marker && !marker.re.test(t)) {
      bad.push({ p, level, marker });
    }
  }
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} numbered paragraph(s) do not match the numbering scheme (e.g. level ${bad[0].level} requires '${bad[0].marker.label}').`, {
    locations: bad.slice(0, 10).map(({ p }) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 60) })),
  })];
};

EVALUATORS["no-single-subparagraph"] = (model, rule) => {
  const scope = paragraphsForScope(model, rule.check.scope);
  for (let i = 0; i < scope.length; i++) {
    const p = scope[i];
    if (!/^\d+\.\t|^\d+\.\s/.test(p.text.trim())) continue;
    const sub = [];
    for (let j = i + 1; j < scope.length; j++) {
      const q = scope[j];
      if (/^\d+\.\t|^\d+\.\s/.test(q.text.trim())) break;
      if (/^[a-z]\.\t/.test(q.text.trim())) sub.push(q);
    }
    if (sub.length === 1) {
      return [finding(rule, `Paragraph ${p.text.trim().split("\t")[0] || p.text.trim().split(" ")[0]} has a single sub-paragraph; a paragraph must never have exactly one sub-paragraph.`, {
        locations: [{ paragraphIndex: p.index, snippet: p.text.slice(0, 60) }, { paragraphIndex: sub[0].index, snippet: sub[0].text.slice(0, 60) }],
      })];
    }
  }
  return [];
};

EVALUATORS["all-caps"] = (model, rule) => {
  const expected = !!rule.check.params.expected;
  const scope = paragraphsForScope(model, rule.check.scope);
  const bad = scope.filter((p) => p.text.trim() && (expected ? p.text !== p.text.toUpperCase() : p.text === p.text.toUpperCase()));
  if (!bad.length) return [];
  return [finding(rule, `${bad.length} item(s) are not in capital letters as required for signal messages.`, {
    locations: bad.slice(0, 10).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
  })];
};

/* ------------------------------------------------------------------ */
/* Text patterns                                                       */
/* ------------------------------------------------------------------ */

EVALUATORS["regex"] = (model, rule) => {
  const params = rule.check.params;
  if (!params.pattern) return [uncheckable(rule, "No pattern supplied.")];
  const re = new RegExp(params.pattern, "m");
  const text = textForScope(model, rule.check.scope);
  const matches = text.match(re);
  const found = !!matches;
  const expect = params.expect || "present";

  if (expect === "absent" && found) {
    return [finding(rule, `Found forbidden text matching '${params.pattern}': "${String(matches[0]).slice(0, 60)}".`, {
      fix: params.mustBeBold ? null : rule.autofix && rule.autofix.available ? { action: "applyRegexFix", params: { pattern: params.pattern } } : null,
    })];
  }
  if (expect === "present" && !found) {
    return [finding(rule, `Required text matching '${params.pattern}' not found.`)];
  }
  if (found && params.mustBeBold) {
    const markings = /TOP SECRET|SECRET|CONFIDENTIAL|RESTRICTED|IN CONFIDENCE|Flag:|Flags:/;
    const scope = paragraphsForScope(model, rule.check.scope);
    const bad = scope.filter((p) => markings.test(p.text) && !p.bold);
    if (bad.length) {
      return [finding(rule, "Security marking / flag reference found but not in bold.", {
        locations: bad.map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 60) })),
        fix: { action: "setBold", params: { bold: true } },
      })];
    }
  }
  return [];
};

EVALUATORS["date-format"] = (model, rule) => {
  const params = rule.check.params;
  const re = new RegExp(params.pattern, "m");
  const text = textForScope(model, rule.check.scope);
  const found = re.test(text);
  const expect = params.expect || "present";
  if (expect === "absent" && found) return [finding(rule, "Date/time written in a non-conforming format.")];
  if (expect === "present" && !found) return [finding(rule, "No conforming date found in the expected format.")];
  return [];
};

EVALUATORS["time-format"] = EVALUATORS["date-format"];

EVALUATORS["dtg-format"] = (model, rule) => {
  const params = rule.check.params;
  if (params.rule === "dtg-after-signature") {
    return [uncheckable(rule, "Verify the DTG was inserted after the releasing officer signed the message.")];
  }
  if (params.rule === "gmt-for-inter-zone") {
    return [uncheckable(rule, "Verify GMT suffix is used for inter-zone messages or messages to addressees outside Kenya.")];
  }
  const re = new RegExp(params.pattern, "m");
  const found = re.test(fullText(model));
  if (!found) return [finding(rule, "No valid Date-Time Group (DDHHMM zone MON YY) found in the message.")];
  return [];
};

/* ------------------------------------------------------------------ */
/* Security / markings                                                 */
/* ------------------------------------------------------------------ */

EVALUATORS["security-marking"] = (model, rule) => {
  const params = rule.check.params;
  const text = fullText(model);
  const allowed = params.allowed || ["TOP SECRET", "SECRET", "CONFIDENTIAL", "RESTRICTED"];
  const found = allowed.filter((c) => text.includes(c));
  if (params.mustMatchDocumentClassification && found.length === 0) {
    return [finding(rule, "Document classification not found in headers/footers.")];
  }
  if (params.privacyMarking && !text.includes(params.privacyMarking)) {
    return [finding(rule, `Privacy marking '${params.privacyMarking}' must appear at top and bottom of every page.`)];
  }
  if (!found.length) {
    return [finding(rule, "No recognised security classification found on the document.")];
  }
  return [];
};

EVALUATORS["copy-number"] = (model, rule) => {
  const params = rule.check.params;
  const text = fullText(model);
  const pattern = params.pattern || /Copy No \d+ of \d+ copies?/;
  const needs = text.includes("TOP SECRET") || text.includes("SECRET") || params.requiredIf === "order";
  if (needs && !pattern.test(text)) {
    return [finding(rule, "Document must bear a copy number (e.g. 'Copy No 1 of 20 copies') in the top right of the first page.", {
      fix: { action: "insertCopyNumber", params: {} },
    })];
  }
  return [];
};

EVALUATORS["precedence-marking"] = (model, rule) => {
  const params = rule.check.params;
  const allowed = params.allowed || ["IMMEDIATE", "PRIORITY"];
  const full = fullText(model);
  const firstPage = textForScope(model, "first-page");
  const foundAny = allowed.filter((w) => new RegExp(`\\b${w}\\b`).test(full));
  if (!foundAny.length) return []; // precedence is optional
  const inFirstPage = allowed.filter((w) => new RegExp(`\\b${w}\\b`).test(firstPage));
  const misplaced = foundAny.filter((w) => !inFirstPage.includes(w));
  if (misplaced.length) {
    return [finding(rule, `Precedence '${misplaced.join(", ")}' must appear in capitals at the top right of the FIRST page only.`)];
  }
  return [];
};

EVALUATORS["signature-block"] = (model, rule) => {
  const params = rule.check.params || {};
  const scope = paragraphsForScope(model, "signature-block");
  const blockText = scope.map((p) => p.text).join("\n");
  if (params.elements) {
    const missing = [];
    if (params.elements.includes("name") && !/[A-Z][A-Z\s]+$/.test(blockText)) missing.push("name (in block capitals)");
    if (params.elements.includes("rank") && !RANKS.test(blockText)) missing.push("rank");
    if (params.elements.includes("appointment") && !/\b(SO\d|Comd|Cmd|Officer|Adm|Ops|Trg|Staff|Bde|Div)\b/i.test(blockText)) missing.push("appointment");
    if (missing.length) return [finding(rule, `Signature block missing: ${missing.join(", ")}.`)];
    return [];
  }
  if (params.rule) return [uncheckable(rule, "Signature rule needs manual verification.")];
  return [];
};

EVALUATORS["distribution-order"] = (model, rule) => {
  return [uncheckable(rule, "Verify addressees are listed: external action, external information, then internal.")];
};

EVALUATORS["draft-marking"] = (model, rule) => {
  const text = textForScope(model, "first-page");
  if (!new RegExp(rule.check.params.keyword || "DRAFT").test(text)) {
    return [finding(rule, "The word 'DRAFT' must appear at the top of the first page, below the security grading.")];
  }
  return [];
};

EVALUATORS["not-first-person"] = (model, rule) => {
  const params = rule.check.params;
  const scope = paragraphsForScope(model, rule.check.scope);
  const text = scope.map((p) => p.text).join(" ");
  const matches = text.match(/\b(I|me|my|mine|we|our|ours)\b/g) || [];
  if (params.firstPersonAllowed === false && matches.length > 2) {
    return [finding(rule, `First-person pronouns used ${matches.length} times; Service correspondence is normally written in the third person.`, {
      locations: scope.filter((p) => /\b(I|me|my|we|our)\b/.test(p.text)).slice(0, 5).map((p) => ({ paragraphIndex: p.index, snippet: p.text.slice(0, 80) })),
    })];
  }
  if (params.firstPersonAllowed === true && !matches.length) {
    return [finding(rule, "DO letters should be written in the first person.")];
  }
  return [];
};

EVALUATORS["abbreviation-usage"] = (model, rule) => {
  const params = rule.check.params;
  const text = textForScope(model, rule.check.scope);
  if (params.rule === "explained-on-first-use") {
    const acro = text.match(/\b[A-Z]{3,}\b/g) || [];
    const unexplained = acro.filter((a) => !new RegExp(`[A-Za-z]+\\s*\\(${a}\\)|\\(${a}\\)`).test(text));
    if (unexplained.length) {
      return [finding(rule, `Abbreviation(s) not explained on first use: ${[...new Set(unexplained)].slice(0, 6).join(", ")}.`)];
    }
    return [];
  }
  if (params.rule === "consistent-use") {
    return [uncheckable(rule, "Verify abbreviations are used consistently throughout headings, tables and text.")];
  }
  if (params.rule === "authorized-only" || params.rule === "authorized-titles-only") {
    return [uncheckable(rule, "Authorized-abbreviation list check: requires the Ch 16 Annex reference data to be loaded.")];
  }
  if (params.rule === "no-introduction-in-headings") {
    return [uncheckable(rule, "Verify abbreviations are not introduced in headings.")];
  }
  if (params.allowed === "none") {
    const acro = text.match(/\b[A-Z]{2,}\b/g) || [];
    if (acro.length) return [finding(rule, `Abbreviations must not be used in letters to civilians (found: ${[...new Set(acro)].slice(0, 6).join(", ")}).`)];
    return [];
  }
  if (params.allowed === "all") return [];
  return [];
};

module.exports = { EVALUATORS, finding, uncheckable };

});

def("engine/engine.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — engine.
 *
 * runCompliance(model, { docType, rulesets, references }) => Report
 *
 *   model      raw OR normalised document model (see model.js); it is
 *              normalised once inside runCompliance before any evaluator runs
 *   docType    selected document type id (see dfswm-rulesets/index.json)
 *   rulesets   array of ruleset objects (id, rules[])
 *   references optional { abbreviations: string[] } for abbreviation checks
 *
 * Report:
 *   { docType, counts: { error, warning, info, manual },
 *     findings: Finding[], rulesEvaluated, rulesSkipped }
 */
"use strict";

const { EVALUATORS, finding, uncheckable } = require("./evaluators.js");
const { normalizeModel, textForScope, fullText } = require("./model.js");

/**
 * True when a rule applies to the selected document type.
 * `general` applies to everything; otherwise the doc type must be listed.
 */
function ruleApplies(rule, docType) {
  const applies = rule.appliesTo || ["general"];
  return applies.includes("general") || applies.includes(docType);
}

function runRule(rule, model, ctx) {
  // Manual rules are always rendered as human checklist items.
  if (rule.manual) {
    return [{ ...uncheckable(rule, rule.notes || rule.description), manual: true }];
  }
  const evaluator = EVALUATORS[rule.check && rule.check.type];
  if (!evaluator) {
    return [{ ...uncheckable(rule, `No evaluator implemented for check type '${rule.check && rule.check.type}'.`), checkable: false }];
  }
  try {
    const results = evaluator(model, rule, ctx) || [];
    return Array.isArray(results) ? results : [results];
  } catch (err) {
    return [{ ...uncheckable(rule, `Evaluator error: ${err.message}`), checkable: false }];
  }
}

/**
 * Run one or more rulesets against the model.
 * @returns {object} report
 */
function runCompliance(rawModel, { docType = "general", rulesets = [], references = null } = {}) {
  // Normalise once so every evaluator sees bodyText, indices and typed
  // fields regardless of whether the caller passed a raw extractor model
  // (Word/PowerPoint) or an already-normalised model. Idempotent.
  const model = normalizeModel(rawModel);
  const ctx = { references, textForScope, fullText };
  const findings = [];
  let rulesEvaluated = 0;
  let rulesSkipped = 0;

  for (const ruleset of rulesets) {
    for (const rule of ruleset.rules || []) {
      if (!ruleApplies(rule, docType)) {
        rulesSkipped += 1;
        continue;
      }
      rulesEvaluated += 1;
      const results = runRule(rule, model, ctx);
      for (const f of results) {
        findings.push({ ...f, rulesetId: ruleset.id, rulesetTitle: ruleset.title || ruleset.id });
      }
    }
  }

  const counts = { error: 0, warning: 0, info: 0, manual: 0 };
  for (const f of findings) {
    if (f.manual) counts.manual += 1;
    else if (f.severity === "error") counts.error += 1;
    else if (f.severity === "warning") counts.warning += 1;
    else counts.info += 1;
  }

  return { docType, counts, findings, rulesEvaluated, rulesSkipped };
}

/**
 * Group findings by severity for the UI.
 */
function groupBySeverity(findings) {
  const order = ["error", "warning", "info", "manual"];
  const groups = { error: [], warning: [], info: [], manual: [] };
  for (const f of findings) {
    const key = f.manual ? "manual" : order.includes(f.severity) ? f.severity : "info";
    groups[key].push(f);
  }
  return { order, groups };
}

module.exports = { runCompliance, runRule, ruleApplies, groupBySeverity };

});

def("word/extractor.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — Word document extractor.
 *
 * Uses the Word JavaScript API to read the open document into the plain
 * normalised model consumed by the engine (see ../engine/model.js).
 * This file only runs inside the Office task pane (browser).
 */
"use strict";

const { pointsToCm } = require("../engine/model.js");

const ALIGN = {
  "Word.Alignment.left": "left",
  "Word.Alignment.centered": "center",
  "Word.Alignment.right": "right",
  "Word.Alignment.justified": "justified",
};

/**
 * Read the open Word document into a model object.
 * @returns {Promise<object>} raw model (pass to normalizeModel)
 */
async function extractDocumentModel() {
  return Word.run(async (context) => {
    const body = context.document.body;
    body.load("text");

    const paragraphs = body.paragraphs;
    paragraphs.load([
      "text", "styleBuiltIn", "alignment", "leftIndent", "firstLineIndent",
      "lineSpacing", "keepWithNext", "keepPrevious",
    ]);
    paragraphs.font.load(["name", "size", "bold", "italic", "underline", "allCaps"]);

    const sections = context.document.sections;
    // Load section page setup + primary header/footer proxies up-front so
    // their .text is available after the first sync (Word JS requires
    // loading a property on the proxy before reading it post-sync).
    const hf = []; // { sectionIndex, header?, footer?, firstPageHeader?, firstPageFooter? }
    for (let s = 0; s < sections.items.length; s++) {
      const section = sections.items[s];
      section.load("pageSetup");
      const pu = section.pageSetup;
      pu.load(["leftMargin", "rightMargin", "topMargin", "bottomMargin", "headerDistance", "footerDistance", "differentFirstPageHeaderFooter"]);
      const entry = { sectionIndex: s, header: null, footer: null };
      // Primary headers/footers always exist, so no guard is needed.
      entry.header = section.getHeader(Word.HeaderFooterType.primary);
      entry.header.load("text");
      entry.footer = section.getFooter(Word.HeaderFooterType.primary);
      entry.footer.load("text");
      hf.push(entry);
    }

    const tables = body.tables;
    tables.load("rowCount");
    for (const t of tables.items) {
      t.load("rowCount");
      for (const r of t.rows.items) {
        r.load("cellCount");
        for (const c of r.cells.items) {
          c.body.load("text");
          c.body.paragraphs.load("text");
          c.body.paragraphs.font.load("size");
        }
      }
    }

    await context.sync();

    // First-page headers/footers only exist when "different first page" is
    // enabled; getHeader(firstPage) otherwise throws at sync time (the
    // throw surfaces when the queued command runs, so try/catch around the
    // call is useless). Gate the requests behind the loaded flag.
    let needsFirstPageSync = false;
    for (let s = 0; s < sections.items.length; s++) {
      const section = sections.items[s];
      if (!section.pageSetup.differentFirstPageHeaderFooter) continue;
      needsFirstPageSync = true;
      const entry = hf[s];
      entry.firstPageHeader = section.getHeader(Word.HeaderFooterType.firstPage);
      entry.firstPageHeader.load("text");
      entry.firstPageFooter = section.getFooter(Word.HeaderFooterType.firstPage);
      entry.firstPageFooter.load("text");
    }
    if (needsFirstPageSync) await context.sync();

    const raw = {
      docType: "general",
      title: null,
      paragraphs: paragraphs.items.map((p) => {
        const f = p.font;
        return {
          text: p.text,
          style: p.styleBuiltIn ? String(p.styleBuiltIn) : null,
          fontName: f.name,
          fontSize: f.size,
          bold: f.bold,
          italic: f.italic,
          underline: !!f.underline,
          allCaps: f.allCaps,
          alignment: ALIGN[p.alignment] || "left",
          firstLineIndentCm: p.firstLineIndent != null ? pointsToCm(p.firstLineIndent) : null,
          blockIndentCm: p.leftIndent != null ? pointsToCm(p.leftIndent) : null,
          lineSpacing: p.lineSpacing === 1.0 ? "single" : p.lineSpacing === 2.0 ? "double" : p.lineSpacing === 1.5 ? "oneAndHalf" : p.lineSpacing,
          keepWithNext: p.keepWithNext,
          keepPrevious: p.keepPrevious,
          headingLevel: null, // resolved by heuristics below
          pageBreakBefore: false,
        };
      }),
      sections: sections.items.map((s, si) => {
        const pu = s.pageSetup;
        const entry = hf[si];
        return {
          margins: {
            left: pu.leftMargin != null ? pointsToCm(pu.leftMargin) : null,
            right: pu.rightMargin != null ? pointsToCm(pu.rightMargin) : null,
            top: pu.topMargin != null ? pointsToCm(pu.topMargin) : null,
            bottom: pu.bottomMargin != null ? pointsToCm(pu.bottomMargin) : null,
          },
          headerDistanceCm: pu.headerDistance != null ? pointsToCm(pu.headerDistance) : null,
          footerDistanceCm: pu.footerDistance != null ? pointsToCm(pu.footerDistance) : null,
          headers: {
            primary: entry && entry.header ? [entry.header.text || ""] : [],
            firstPage: entry && entry.firstPageHeader ? [entry.firstPageHeader.text || ""] : [],
            evenPages: [],
          },
          footers: {
            primary: entry && entry.footer ? [entry.footer.text || ""] : [],
            firstPage: entry && entry.firstPageFooter ? [entry.firstPageFooter.text || ""] : [],
            evenPages: [],
          },
        };
      }),
      tables: tables.items.map((t) => ({
        headerRow: t.rows.items[0] ? t.rows.items[0].cells.items.map((c) => c.body.text) : [],
        rows: t.rows.items.map((r) => r.cells.items.map((c) => {
          const sizes = c.body.paragraphs.items.map((cp) => cp.font.size).filter((n) => n != null);
          return { text: c.body.text, fontSize: sizes.length ? sizes[0] : null };
        })),
      })),
      footnotes: [], // Word JS does not expose footnotes reliably; handled as manual
    };

    // Heading-level heuristic: bold + centered + short + all-caps => subject/main;
    // bold + caps + left => group; bold + title case => paragraph heading.
    raw.paragraphs.forEach((p) => {
      const t = p.text.trim();
      if (!t) return;
      const short = t.length <= 90;
      if (!p.bold || !short) return;
      const allCaps = t === t.toUpperCase();
      if (p.alignment === "center" && allCaps) p.headingLevel = "subject";
      else if (allCaps && p.alignment !== "center") p.headingLevel = "group";
      else if (/^[A-Z][a-z]/.test(t)) p.headingLevel = "paragraph";
    });

    return raw;
  });
}

module.exports = { extractDocumentModel };

});

def("word/fixer.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — autofix layer.
 *
 * Applies simple, safe fixes to the open Word document. Each fix is an
 * object produced by an evaluator: { action, params }.
 */
"use strict";

const ALIGN = {
  left: "Word.Alignment.left",
  center: "Word.Alignment.centered",
  right: "Word.Alignment.right",
  justified: "Word.Alignment.justified",
};

async function applyFix(fix) {
  if (!fix || !fix.action) return { ok: false, message: "No fix provided." };
  try {
    switch (fix.action) {
      case "setFont":
        return await Word.run(async (context) => {
          const body = context.document.body;
          body.font.name = fix.params.fontName;
          await context.sync();
          return { ok: true, message: `Font set to ${fix.params.fontName}.` };
        });
      case "setFontSize":
        return await Word.run(async (context) => {
          const body = context.document.body;
          body.font.size = fix.params.size;
          await context.sync();
          return { ok: true, message: `Body font size set to ${fix.params.size} pt.` };
        });
      case "setAlignment":
        return await Word.run(async (context) => {
          const body = context.document.body;
          body.paragraphs.load("alignment");
          await context.sync();
          for (const p of body.paragraphs.items) {
            p.alignment = ALIGN[fix.params.alignment] || "Word.Alignment.justified";
          }
          await context.sync();
          return { ok: true, message: `Alignment set to ${fix.params.alignment}.` };
        });
      case "setBold":
        return await Word.run(async (context) => {
          const body = context.document.body;
          body.font.bold = fix.params.bold;
          await context.sync();
          return { ok: true, message: `Bold ${fix.params.bold ? "applied" : "removed"}.` };
        });
      case "removeUnderline":
        return await Word.run(async (context) => {
          const body = context.document.body;
          body.font.underline = "Word.UnderlineType.none";
          await context.sync();
          return { ok: true, message: "Underlining removed." };
        });
      case "setLineSpacing":
        return await Word.run(async (context) => {
          const body = context.document.body;
          const spacing = fix.params.spacing === "double" ? 2.0 : fix.params.spacing === "oneAndHalf" ? 1.5 : 1.0;
          for (const p of body.paragraphs.items) {
            p.lineSpacing = spacing;
          }
          await context.sync();
          return { ok: true, message: `Line spacing set to ${fix.params.spacing}.` };
        });
      case "setMargins":
        return await Word.run(async (context) => {
          const sections = context.document.sections;
          const cmToPt = (cm) => cm * 28.3465;
          for (const s of sections.items) {
            const pu = s.pageSetup;
            if (fix.params.target === "header-footer") {
              pu.headerDistance = cmToPt(fix.params.valueCm);
              pu.footerDistance = cmToPt(fix.params.valueCm);
            } else {
              const sides = Array.isArray(fix.params.sides) ? fix.params.sides : [];
              if (sides.includes("left")) pu.leftMargin = cmToPt(fix.params.valueCm);
              if (sides.includes("right")) pu.rightMargin = cmToPt(fix.params.valueCm);
              if (sides.includes("top")) pu.topMargin = cmToPt(fix.params.valueCm);
              if (sides.includes("bottom")) pu.bottomMargin = cmToPt(fix.params.valueCm);
            }
          }
          await context.sync();
          return {
            ok: true,
            message: fix.params.target === "header-footer"
              ? `Header/footer distance set to ${fix.params.valueCm} cm.`
              : "Margins updated.",
          };
        });
      case "keepWithNext":
        return await Word.run(async (context) => {
          const body = context.document.body;
          for (const p of body.paragraphs.items) {
            p.keepWithNext = true;
          }
          await context.sync();
          return { ok: true, message: "Keep-with-next applied to prevent hanging headings." };
        });
      case "insertPageNumber":
        // Word JS cannot insert a PAGE field directly; instruct the user.
        return { ok: false, message: "Insert the page number manually: Insert tab > Page Number > Bottom Center." };
      case "insertCopyNumber":
        return await Word.run(async (context) => {
          const body = context.document.body;
          const range = body.insertText("\nCopy No 1 of 1 copy\n", "Word.InsertLocation.start");
          range.load("text");
          await context.sync();
          return { ok: true, message: "Copy number placeholder inserted at the top of the document." };
        });
      default:
        return { ok: false, message: `No implementation for fix action '${fix.action}'.` };
    }
  } catch (err) {
    return { ok: false, message: err.message };
  }
}

module.exports = { applyFix };

});

def("powerpoint/extractor.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — PowerPoint presentation extractor.
 *
 * Maps the open presentation into the same plain, serialisable model the
 * Word extractor produces (see ../engine/model.js), so the engine and its
 * evaluators are host-agnostic. Each text-bearing shape's paragraphs become
 * model paragraphs tagged with their slideIndex.
 *
 * This file only runs inside the Office task pane (browser). The pure
 * mapping function is exported so it can be unit-tested in Node.
 */
"use strict";

const PPT_ALIGN = {
  "Left": "left",
  "Center": "center",
  "Right": "right",
  "Justify": "justified",
  "Distribute": "justified",
  "JustifyLow": "justified",
  "ThaiDistribute": "justified",
};

/**
 * Pure mapping: plain slide data -> raw model (same shape as the Word
 * extractor's output, consumable directly by the engine).
 *
 * slidesData: [{ name, shapes: [{ name, hasTextFrame,
 *   paragraphs: [{ text, fontName, fontSize, bold, italic, underline,
 *                  alignment }] }] }]
 */
function mapPresentationToModel(slidesData) {
  const paragraphs = [];
  (slidesData || []).forEach((slide, slideIndex) => {
    (slide.shapes || []).forEach((shape) => {
      if (!shape.hasTextFrame) return;
      (shape.paragraphs || []).forEach((p) => {
        const t = String(p.text || "").trim();
        if (!t) return;
        paragraphs.push({
          text: t,
          style: null,
          fontName: p.fontName || null,
          fontSize: p.fontSize ?? null,
          bold: !!p.bold,
          italic: !!p.italic,
          underline: !!p.underline,
          allCaps: false, // PPT font.allCaps is not reliably exposed; evaluators compare text
          alignment: PPT_ALIGN[p.alignment] || "left",
          firstLineIndentCm: null,
          blockIndentCm: null,
          lineSpacing: null,
          keepWithNext: false,
          keepPrevious: false,
          headingLevel: null,
          pageBreakBefore: false,
          slideIndex,
        });
      });
    });
  });

  // Heading heuristic (mirrors the Word extractor): bold + short text.
  paragraphs.forEach((p) => {
    const t = p.text.trim();
    if (!t) return;
    if (t.length > 90 || !p.bold) return;
    const allCaps = t === t.toUpperCase();
    if (p.alignment === "center" && allCaps) p.headingLevel = "subject";
    else if (allCaps && p.alignment !== "center") p.headingLevel = "group";
    else if (/^[A-Z][a-z]/.test(t)) p.headingLevel = "paragraph";
  });

  return {
    docType: "presentation",
    title: null,
    paragraphs: paragraphs.map((p, i) => ({ ...p, index: i })),
    sections: [], // PowerPoint has no page setup; layout rules do not apply
    tables: [],
    footnotes: [],
  };
}

/**
 * Read the open presentation into a model object via the PowerPoint JS API.
 * @returns {Promise<object>} raw model (consumed directly by runCompliance)
 */
async function extractPresentationModel() {
  return PowerPoint.run(async (context) => {
    const slides = context.presentation.slides;
    const slideData = [];
    const jobs = []; // { slide, shape, paragraphs }

    for (let s = 0; s < slides.items.length; s++) {
      const slide = slides.items[s];
      const shapes = slide.shapes;
      const shapesData = [];
      for (let i = 0; i < shapes.items.length; i++) {
        const shape = shapes.items[i];
        shape.load("name");
        shape.load("hasTextFrame");
        shapesData.push({ name: null, hasTextFrame: false, paragraphs: [] });
        jobs.push({ slideIndex: s, shape, shapeData: shapesData[shapesData.length - 1] });
      }
      slideData.push({ name: null, shapes: shapesData });
    }
    await context.sync();

    // Second pass: for shapes with a text frame, load paragraph text and
    // per-paragraph font/alignment via path-based loads so every item's
    // child properties are populated after the sync.
    for (const job of jobs) {
      if (!job.shape.hasTextFrame) continue;
      const textRange = job.shape.textFrame.textRange;
      const paras = textRange.paragraphs;
      paras.load("text, font/name, font/size, font/bold, font/italic, font/underline, paragraphFormat/alignment");
      job.paras = paras;
    }
    await context.sync();

    // Read the loaded values into plain data.
    for (const job of jobs) {
      job.shapeData.name = job.shape.name;
      job.shapeData.hasTextFrame = job.shape.hasTextFrame;
      if (!job.paras) continue;
      for (const p of job.paras.items) {
        job.shapeData.paragraphs.push({
          text: p.text,
          fontName: p.font.name,
          fontSize: p.font.size,
          bold: p.font.bold,
          italic: p.font.italic,
          underline: p.font.underline,
          alignment: p.paragraphFormat.alignment,
        });
      }
    }

    return mapPresentationToModel(slideData);
  });
}

module.exports = { extractPresentationModel, mapPresentationToModel };

});

def("powerpoint/fixer.js", function (module, exports, require) {
/**
 * DFSWM Compliance Plugin — PowerPoint autofix layer.
 *
 * Applies the subset of fix actions that make sense on slides using the
 * PowerPoint JavaScript API. Word-only actions (margins, page numbers, line
 * spacing, keep-with-next, copy numbers) return ok:false with instructions.
 */
"use strict";

const PPT_ALIGN = {
  left: "Left",
  center: "Center",
  right: "Right",
  justified: "Justify",
};

/**
 * Iterate every text-bearing shape in the deck and apply a font-level
 * mutation queued inside a single PowerPoint.run batch.
 * @param {function} applyFont (font, context) => void
 */
async function mutateAllText(applyFont) {
  return PowerPoint.run(async (context) => {
    const slides = context.presentation.slides;
    const jobs = [];
    for (let s = 0; s < slides.items.length; s++) {
      const shapes = slides.items[s].shapes;
      for (let i = 0; i < shapes.items.length; i++) {
        const shape = shapes.items[i];
        shape.load("hasTextFrame");
        jobs.push(shape);
      }
    }
    await context.sync();
    for (const shape of jobs) {
      if (!shape.hasTextFrame) continue;
      const font = shape.textFrame.textRange.font;
      applyFont(font);
    }
    await context.sync();
  });
}

/**
 * Apply a fix object produced by an evaluator.
 * @returns {Promise<{ok: boolean, message: string}>}
 */
async function applyFix(fix) {
  if (!fix || !fix.action) return { ok: false, message: "No fix provided." };
  try {
    switch (fix.action) {
      case "setFont":
        await mutateAllText((font) => {
          font.name = fix.params.fontName;
        });
        return { ok: true, message: `Font set to ${fix.params.fontName} on all slide text.` };
      case "setFontSize":
        await mutateAllText((font) => {
          font.size = fix.params.size;
        });
        return { ok: true, message: `Font size set to ${fix.params.size} pt on all slide text.` };
      case "setBold":
        await mutateAllText((font) => {
          font.bold = fix.params.bold;
        });
        return { ok: true, message: `Bold ${fix.params.bold ? "applied" : "removed"} on all slide text.` };
      case "removeUnderline":
        await mutateAllText((font) => {
          font.underline = "None";
        });
        return { ok: true, message: "Underlining removed from all slide text." };
      case "setAlignment":
        return await PowerPoint.run(async (context) => {
          const slides = context.presentation.slides;
          const jobs = [];
          for (let s = 0; s < slides.items.length; s++) {
            const shapes = slides.items[s].shapes;
            for (let i = 0; i < shapes.items.length; i++) {
              const shape = shapes.items[i];
              shape.load("hasTextFrame");
              jobs.push(shape);
            }
          }
          await context.sync();
          for (const shape of jobs) {
            if (!shape.hasTextFrame) continue;
            const paras = shape.textFrame.textRange.paragraphs;
            paras.load("text");
            for (const p of paras.items) {
              p.paragraphFormat.alignment = PPT_ALIGN[fix.params.alignment] || "Left";
            }
          }
          await context.sync();
          return { ok: true, message: `Alignment set to ${fix.params.alignment}.` };
        });
      default:
        return { ok: false, message: `Fix '${fix.action}' is not supported in PowerPoint — apply it manually.` };
    }
  } catch (err) {
    return { ok: false, message: err.message };
  }
}

module.exports = { applyFix };

});

  var require = makeRequire("");
  window.DFSWM = {
    runCompliance: require("engine/engine.js").runCompliance,
    groupBySeverity: require("engine/engine.js").groupBySeverity,
    normalizeModel: require("engine/model.js").normalizeModel,
    extractDocumentModel: require("word/extractor.js").extractDocumentModel,
    applyFix: require("word/fixer.js").applyFix,
    extractPresentationModel: require("powerpoint/extractor.js").extractPresentationModel,
    applyPptFix: require("powerpoint/fixer.js").applyFix
  };
})();
